package dev.jlynx.langcontrol.generator.openai.dto;

import com.fasterxml.jackson.annotation.JsonValue;

/**
 * Represents the role of a message sender in a conversation, typically used within
 * OpenAI chat-based interactions.
 * <p>
 * The {@code ChatMessageRole} enum defines three distinct roles:
 * <ul>
 *   <li>{@code SYSTEM}: Represents messages generated by the system itself. These are typically
 *   instructions or metadata used to guide the behaviour of the conversation.</li>
 *   <li>{@code USER}: Represents messages sent by the user, typically as queries, commands, or conversational input.</li>
 *   <li>{@code ASSISTANT}: Represents responses generated by the assistant or conversational model,
 *   designed to address user inputs or system instructions.</li>
 * </ul>
 *
 * <p>
 * The {@code ChatMessageRole} is commonly used in classes such as {@link ChatCompletionRequest.ChatMessage}
 * to classify and structure the context of conversations for OpenAI's APIs.
 * </p>
 */
public enum ChatMessageRole {

    SYSTEM, USER, ASSISTANT;

    /**
     * Returns the name of the current {@link ChatMessageRole} instance in lowercase format.
     * <p>
     * This method ensures that the enumerated value, as defined in the {@link ChatMessageRole}
     * enum, is serialised into a lowercase string representation. It is annotated with
     * {@code @JsonValue}, allowing the returned string to be used during serialisation when
     * converting this role to JSON format.
     * </p>
     *
     * @return A {@code String} representing the lowercase name of the current role, such as
     *         {@code "system"}, {@code "user"} or {@code "assistant"}.
     */
    @JsonValue
    public String getValue() {
        return this.name().toLowerCase();
    }
}
